html:
{% set ri = get_ri_data(doc) %}
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, Helvetica, sans-serif; font-size: 8px; color: #000; margin: 0; }
  .header { width: 100%; border: 1px solid #000; padding: 3px 5px; }
  .header td { vertical-align: top; }
  .brand-title { font-size: 11px; font-weight: bold; }
  .k { color: #333; }
  .v { font-weight: bold; }
  .tipo { font-size: 11px; font-weight: bold; text-align: right; }
  .small { font-size: 7px; }
  .kv { text-align: right; margin-top: 2px; }
  table { width: 100%; border-collapse: collapse; }
  .items th, .items td { border: 1px solid #000; padding: 1px 3px; }
  .items th { background: #eee; text-align: center; font-size: 7px; }
  .num { text-align: right; }
  .center { text-align: center; }
  .totales { width: 45%; float: right; margin-top: 3px; }
  .totales td { border: 1px solid #000; padding: 1px 4px; }
  .totales .lbl { background: #eee; }
  .cliente { border: 1px solid #000; padding: 3px 5px; margin-top: 3px; }
  .pie { margin-top: 3mm; }
  .qr-box { width: 25mm; height: 25mm; }
  .legal { font-size: 7px; color: #333; }
</style>
</head>
<body>
<div class="ri-page">
  <table class="header" style="border: none; padding: 0">
    <tr>
      <td style="width: 58%; border: 1px solid #000; padding: 3px 5px">
        <div class="brand-title">{{ ri.razon_social_emisor }}</div>
        {% if ri.nombre_comercial %}<div>Nombre Comercial: {{ ri.nombre_comercial }}</div>{% endif %}
        {% if ri.sucursal %}<div>Sucursal: {{ ri.sucursal }}</div>{% endif %}
        <div>RNC: {{ ri.rnc_emisor }}</div>
        <div>Direcci&oacute;n: {{ ri.direccion_emisor }}</div>
        {% if ri.municipio %}<div>Municipio: {{ ri.municipio }}</div>{% endif %}
        {% if ri.provincia %}<div>Provincia: {{ ri.provincia }}</div>{% endif %}
        <div>Fecha de Emisi&oacute;n: {{ ri.fecha_emision }}</div>
      </td>
      <td style="width: 42%; border: 1px solid #000; padding: 3px 5px">
        <div class="tipo">{{ ri.tipo_desc }}</div>
        <div class="kv"><span class="k">e-NCF:</span> <span class="v">{{ ri.encf }}</span></div>
        {% if ri.fecha_vencimiento %}<div class="kv"><span class="k">Fecha Vencimiento:</span> <span>{{ ri.fecha_vencimiento }}</span></div>{% endif %}
        {% if ri.ncf_modificado %}
        <div class="kv"><span class="k">e-NCF Modificado:</span> <span class="v">{{ ri.ncf_modificado }}</span></div>
        <div class="kv"><span class="k">C&oacute;digo de Modificaci&oacute;n:</span> <span>{{ ri.codigo_modificacion }} - {{ ri.codigo_modificacion_desc }}</span></div>
        {% endif %}
      </td>
    </tr>
  </table>

  <div class="cliente">
    <strong>Cliente:</strong> {{ ri.razon_social_comprador or 'Consumidor Final' }}
    {% if ri.rnc_comprador %} &nbsp; <strong>RNC:</strong> {{ ri.rnc_comprador }}{% endif %}
  </div>

  <table class="items" style="margin-top: 6px">
    <thead>
      <tr>
        <th style="width: 8%">Cantidad</th>
        <th style="width: 5%">Ind.</th>
        <th>Descripci&oacute;n</th>
        <th style="width: 8%">Unidad</th>
        <th style="width: 10%">Precio</th>
        <th style="width: 9%">Descuento</th>
        <th style="width: 9%">Recargo</th>
        <th style="width: 11%">Valor</th>
      </tr>
    </thead>
    <tbody>
    {% for it in ri.lineas %}
      <tr>
        <td class="num">{{ it.cantidad }}</td>
        <td class="center">{{ 'E' if it.exento else '' }}</td>
        <td>{{ it.descripcion }}</td>
        <td class="center">{{ it.unidad or '' }}</td>
        <td class="num">{{ it.precio or '' }}</td>
        <td class="num">{{ it.descuento or '' }}</td>
        <td class="num">{{ it.recargo or '' }}</td>
        <td class="num">{{ it.valor }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>

  <table class="totales">
    {% if ri.totales.monto_gravado_total %}<tr><td class="lbl">Subtotal Gravado</td><td class="num">{{ ri.totales.monto_gravado_total }}</td></tr>{% endif %}
    {% if ri.totales.monto_exento %}<tr><td class="lbl">Subtotal Exento</td><td class="num">{{ ri.totales.monto_exento }}</td></tr>{% endif %}
    {% if ri.totales.monto_impuesto_adicional %}<tr><td class="lbl">Impuesto Adicional</td><td class="num">{{ ri.totales.monto_impuesto_adicional }}</td></tr>{% endif %}
    {% if ri.totales.total_itbis %}<tr><td class="lbl">Total ITBIS</td><td class="num">{{ ri.totales.total_itbis }}</td></tr>{% endif %}
    <tr><td class="lbl"><strong>Total</strong></td><td class="num"><strong>{{ ri.totales.monto_total }}</strong></td></tr>
  </table>
  <div style="clear: both"></div>

  <div class="pie">
    <table style="width: 100%">
      <tr>
        <td style="width: 30mm; vertical-align: bottom">
          <img class="qr-box" src="{{ ri.qr_data_uri }}" />
        </td>
        <td style="vertical-align: bottom" class="small">
          <div><strong>C&oacute;digo de Seguridad:</strong> {{ ri.codigo_seguridad }}</div>
          <div><strong>Fecha de Firma Digital:</strong> {{ ri.fecha_firma }}</div>
          <div class="legal">Representaci&oacute;n Impresa de un Comprobante Fiscal Electr&oacute;nico (e-CF).</div>
        </td>
      </tr>
    </table>
  </div>
</div>
</body>
</html>
